import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
data = json.loads((HERE / 'Themes.json').read_text(encoding='utf-8'))
template = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Deadly Jenga · Abstract Surface Review</title>
<style>
:root{color-scheme:dark;--bg:#10141a;--panel:#1a212a;--line:#35404d;--ink:#f3f0e8;--muted:#bac3ce;--accent:#a9e5ce}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 system-ui,sans-serif}a{color:var(--accent)}button,select,textarea,input{font:inherit;color:inherit;background:var(--panel);border:1px solid var(--line);border-radius:7px;padding:9px 13px}button,a,select{touch-action:manipulation}button{cursor:pointer}button:hover{border-color:var(--accent)}button[aria-pressed=true]{border-color:var(--accent);background:#263d38}header{padding:26px 32px 20px;border-bottom:1px solid var(--line)}header p{margin:4px 0;color:var(--muted)}.eyebrow{font-size:12px;letter-spacing:.18em;text-transform:uppercase;color:var(--accent)}h1{font-size:clamp(26px,4vw,42px);margin:4px 0}h2{font-size:30px;margin:6px 0}h3{margin:8px 0}.shell{max-width:1600px;margin:auto;padding:24px 32px}.toolbar{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin-bottom:22px}.toolbar label{display:flex;align-items:center;gap:10px}select{max-width:100%}.fit{max-width:900px;color:var(--muted)}.themes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:24px 0}.theme{text-align:left;padding:18px;min-width:0}.theme small{color:var(--muted)}.swatches{display:flex;gap:6px;margin:10px 0}.swatch{height:13px;flex:1;border-radius:3px}.theme-title{font-size:19px;font-weight:650}.theme p{margin:10px 0 0;font-size:14px;line-height:1.6}.board{background:#080c10;border:1px solid var(--line);border-radius:10px;overflow:hidden}.board img{display:block;width:100%;height:auto}.caption{padding:12px 16px;color:var(--muted);font-size:14px}.actions{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:14px 0 26px}.originals{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.originals img{display:block;width:100%;border-radius:7px}.originals figure{margin:0}.originals figcaption{font-size:14px;color:var(--muted)}details{border-top:1px solid var(--line);padding:20px 0;margin-top:24px}summary{cursor:pointer;font-size:20px}textarea{display:block;width:100%;min-height:90px;margin:12px 0}.hint{font-size:13px;color:var(--muted)}.pill{display:inline-block;border:1px solid var(--line);border-radius:20px;padding:3px 10px;font-size:12px;color:var(--muted)}.status{min-height:24px;color:var(--accent);font-size:13px}footer{padding:28px 0;color:var(--muted)}:focus-visible{outline:3px solid var(--accent);outline-offset:3px}@media(max-width:800px){header,.shell{padding:20px 16px}.themes{grid-template-columns:1fr}.originals{grid-template-columns:1fr}.toolbar label{width:100%;display:block}select{width:100%}}
</style></head><body>
<header><div class="eyebrow">Deadly Jenga / Art direction / October 26, 2026</div><h1>Ten playgrounds. Thirty tactile worlds.</h1><p>Revised direction: shape-specific textures, top / edge / underside treatments, and sparse attached visual details.</p><span class="pill">AI concepts · not implemented Unity materials</span></header><p><a href="settings.html">NEW: Eight requested world settings — hive, carnival cloud, lilypad, jungle leaf, sandbox, western, candy-glass cloud and tiny moon →</a></p>
<main class="shell"><nav class="toolbar" aria-label="Map navigation"><button id="prev">← Previous</button><label for="map">Map <select id="map"></select></label><button id="next">Next →</button><span id="counter" class="hint"></span></nav>
<h2 id="name"></h2><p id="fit" class="fit"></p><div id="themes" class="themes"></div>
<div class="board"><a id="boardLink" target="_blank" rel="noopener"><img id="board" alt="Three proposed material and environment themes"></a><div class="caption">Top = A · Middle = B · Bottom = C. These AI paintovers explore mood and surfaces; they can drift from exact geometry. The original captures below remain the authority. Macro details show proposed surface treatments, not installed Unity assets. Any distant scenery is backdrop art. Small silhouette changes in AI images are not an implementation instruction.</div></div>
<div class="actions"><a id="open" target="_blank" rel="noopener">Open full-resolution comparison ↗</a><button id="fullscreen">Fullscreen comparison</button><label>Review <select id="review"><option value="unreviewed">Unreviewed</option><option value="favorite">Favorite</option><option value="revise">Revise</option><option value="approved">Approved concept</option></select></label></div>
<details open><summary id="specTitle">Selected surface treatment</summary><ul id="spec"></ul></details><label for="notes">Notes for the selected theme</label><textarea id="notes" placeholder="What works? What should change?"></textarea><div class="actions"><button id="export">Export review notes</button><span class="hint">Saved in this browser when storage is available. Export keeps a portable copy.</span></div><div id="status" class="status" aria-live="polite"></div>
<h3>Original Unity shape references</h3><p class="hint">Street-level layers · Landmark and neighborhood · Connected rooftops. Open an image for the full 1920 × 1200 capture.</p><div id="originals" class="originals"></div><details><summary>Original whole-map shape reference</summary><a id="overviewLink" target="_blank" rel="noopener"><img id="overview" style="width:100%;height:auto" alt="Actual Unity whole-map geometry reference"></a></details>
<details><summary>How these themes would stay visual and economical</summary><p>Keep every collider, rigidbody, slab, pillar, passage and map boundary. Give large panels, narrow posts, tops and undersides different surface treatments instead of assigning city-building functions. Concentrate sparse ornaments at exterior corners and back faces; leave walking surfaces, grip faces and sight lines clear. Use a small shared opaque material family, surface textures, restrained emissive masks and an environment preset. Keep top faces readable and quieter than side faces; preserve block seams so loose pieces remain understandable after collapse. Nothing shown here has been performance-tested or applied in Unity.</p><p>Jungle motifs can start as bark, moss and leaf-litter surface patterns; neon as emission rather than hundreds of lights; water as a palette and surface treatment; stars, planets, cloud banks and distant silhouettes as backdrop art. Sparse ornaments would attach to existing pieces without their own physics bodies or colliders. They still add rendering cost and need a measured budget. Gloss, water, lighting and shader costs still need measurement on device.</p><p>The concepts retain the existing water boundary as a visual reference. Alternate no-ocean presentations should retain that boundary and clearly depict the danger, rather than making a lethal fall look like safe solid ground. Frost, apparent rain, lava patterns and amber seas add no new gameplay hazards or traction changes.</p><p>For night themes, use enough ambient fill to read other players and the undersides of decks. Team colors and objective markers must remain distinct from the environment; color alone should never identify the route or danger.</p></details>
<details><summary>Natural reference sources</summary><p>These are original shape-led proposals. Natural materials and optical patterns provide references; the structures are abstract playgrounds, not literal city buildings.</p><ul>

<li><a href="https://oceanservice.noaa.gov/facts/biolum.html?lv=true" target="_blank" rel="noopener">NOAA: bioluminescence</a> — inspiration for glowing ocean and organic surface motifs.</li>
<li><a href="https://home.nps.gov/whsa/learn/geology-of-white-sands.htm" target="_blank" rel="noopener">National Park Service: White Sands geology</a> — gypsum whites and mineral texture for Sunbleached Salt Circuit.</li>
<li><a href="https://science.nasa.gov/earth/earth-observatory/solar-evaporation-ponds-near-moab-utah-90698/" target="_blank" rel="noopener">NASA: evaporation ponds near Moab</a> — saturated blue water against pale mineral terrain; the pink salt-ocean proposal is a creative extrapolation.</li>
</ul><p><a href="Themes.json">Theme specifications</a> · <a href="Prompts.json">Exact image prompts</a> · <a href="../EpicCityCinematics-20261026/index.html">Original cinematic gallery</a></p></details>
<footer>Prepared for visual selection. No gameplay geometry, Unity materials, physics or scenes changed.</footer></main>
<script>
const data=__DATA__;const maps=data.maps;const $=id=>document.getElementById(id);let index=0,selected=0,reviews={};let storage=true;
try{reviews=JSON.parse(localStorage.getItem('dj-city-surface-review-v3')||'{}')}catch(e){storage=false}
function key(){return maps[index].id+':'+selected}function persist(){try{localStorage.setItem('dj-city-surface-review-v3',JSON.stringify(reviews));$('status').textContent='Saved in this browser.'}catch(e){storage=false;$('status').textContent='Browser storage unavailable. Export notes to keep them.'}}
function selectTheme(n){selected=n;document.querySelectorAll('.theme').forEach((b,i)=>b.setAttribute('aria-pressed',i===n?'true':'false'));$('specTitle').textContent=maps[index].themes[n][0]+' — surface and detail plan';$('spec').replaceChildren();maps[index].themes[n][1].split('. ').forEach(text=>{const li=document.createElement('li');li.textContent=text;$('spec').append(li)});const r=reviews[key()]||{};$('review').value=r.status||'unreviewed';$('notes').value=r.notes||'';$('notes').setAttribute('aria-label','Notes for '+maps[index].themes[n][0]);$('status').textContent=storage?'Selected '+String.fromCharCode(65+n)+' · '+maps[index].themes[n][0]:'Storage unavailable; use Export review notes.'}
function render(){const m=maps[index];$('map').value=m.id;$('name').textContent=m.name;$('fit').textContent=m.fit;$('counter').textContent=(index+1)+' / '+maps.length;$('themes').replaceChildren();m.themes.forEach((t,i)=>{const b=document.createElement('button');b.className='theme';b.type='button';const small=document.createElement('small');small.textContent='OPTION '+String.fromCharCode(65+i);const title=document.createElement('div');title.className='theme-title';title.textContent=t[0];const sw=document.createElement('div');sw.className='swatches';t.slice(2).forEach(c=>{const span=document.createElement('span');span.className='swatch';span.style.background=c;span.title=c;sw.append(span)});const p=document.createElement('p');p.textContent=t[1].split('. ')[0]+'.';b.append(small,title,sw,p);b.onclick=()=>selectTheme(i);$('themes').append(b)});const whole='../EpicCitiesWoven-20261025/Captures/'+String(index+1).padStart(2,'0')+'-intact.png';$('overview').src=whole;$('overviewLink').href=whole;const src=m.id+'-themes.png';$('board').src=src;$('board').alt=m.name+' — A: '+m.themes[0][0]+', B: '+m.themes[1][0]+', C: '+m.themes[2][0];$('boardLink').href=src;$('open').href=src;$('originals').replaceChildren();['Street-level layers','Landmark and neighborhood','Connected rooftops'].forEach((label,i)=>{const f=document.createElement('figure');const a=document.createElement('a');a.href='../EpicCityCinematics-20261026/'+m.id+'-0'+(i+1)+'.png';a.target='_blank';a.rel='noopener';const img=document.createElement('img');img.src=a.href;img.loading='lazy';img.alt=m.name+' — original '+label;const cap=document.createElement('figcaption');cap.textContent=label;a.append(img);f.append(a,cap);$('originals').append(f)});history.replaceState(null,'','#'+m.id);selectTheme(0)}
maps.forEach(m=>{const o=document.createElement('option');o.value=m.id;o.textContent=m.name;$('map').append(o)});const initial=maps.findIndex(m=>m.id===location.hash.slice(1));if(initial>=0)index=initial;
$('map').onchange=()=>{index=maps.findIndex(m=>m.id===$('map').value);render()};$('prev').onclick=()=>{index=(index+maps.length-1)%maps.length;render()};$('next').onclick=()=>{index=(index+1)%maps.length;render()};function save(){reviews[key()]={mapId:maps[index].id,theme:maps[index].themes[selected][0],status:$('review').value,notes:$('notes').value};persist()}$('review').onchange=save;$('notes').oninput=save;
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({exported:new Date().toISOString(),reviews},null,2)],{type:'application/json'});const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download='DeadlyJenga-surface-theme-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('fullscreen').onclick=async()=>{try{await $('board').requestFullscreen()}catch(e){$('status').textContent='Use Open full-resolution comparison for a larger view.'}};render();
</script></body></html>'''
(HERE / 'index.html').write_text(template.replace('__DATA__', json.dumps(data).replace('</','<\\/')), encoding='utf-8')
print('Built ten-map, thirty-theme local gallery')
